		SELECT
			NetNodeID as nodeID,
			SensorCode,
			SensorValue,
			ExtraValue,
			TimeStamp
		FROM
			${tableName}
		WHERE 
			NetNodeID = #{nodeID}
			AND SensorCode = #{sensorCode}
			AND TimeStamp BETWEEN #{timeFrom}
			AND #{timeTo}
		ORDER BY ID 

    		LIMIT #{maxCount}

SELECT
	NetNodeID as nodeID,
	SensorCode,
	max(SensorValue) as SensorValue,
	ExtraValue,
	TimeStamp
FROM
	${tableName}
WHERE 
	NetNodeID = #{nodeID}
	AND SensorCode = #{sensorCode}
	AND TimeStamp BETWEEN #{timeFrom}
	AND #{timeTo}
ORDER BY ID

