UPDATE ${tableName} 
SET
	SensorValue=#{sensorValue},
	ExtraValue=#{extraValue},
	TimeStamp=#{timeStampString}
WHERE
	NetNodeID=#{nodeID} AND SensorCode=#{sensorCode}

